'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const N = input[pos++];
const M = input[pos++];
const values = new Array(N);
for (let i = 0; i < N; i++) values[i] = input[pos++];

function gcd(a, b) {
  while (b !== 0) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function leaf(value) {
  return {
    g: value,
    good: value > 1 ? 1 : 0,
    pg: [value],
    pc: [1],
    sg: [value],
    sc: [1]
  };
}

function appendGrouped(gs, cs, value, count) {
  const last = gs.length - 1;
  if (last >= 0 && gs[last] === value) {
    cs[last] += count;
  } else {
    gs.push(value);
    cs.push(count);
  }
}

function merge(a, b) {
  if (!a) return b;
  if (!b) return a;

  let cross = 0;
  for (let i = 0; i < a.sg.length; i++) {
    const x = a.sg[i];
    for (let j = 0; j < b.pg.length; j++) {
      const y = b.pg[j];
      if (x > 1 && y > 1 && gcd(x, y) > 1) {
        cross += a.sc[i] * b.pc[j];
      }
    }
  }

  const pg = a.pg.slice();
  const pc = a.pc.slice();
  for (let i = 0; i < b.pg.length; i++) {
    appendGrouped(pg, pc, gcd(a.g, b.pg[i]), b.pc[i]);
  }

  const sg = b.sg.slice();
  const sc = b.sc.slice();
  for (let i = 0; i < a.sg.length; i++) {
    appendGrouped(sg, sc, gcd(b.g, a.sg[i]), a.sc[i]);
  }

  return {
    g: gcd(a.g, b.g),
    good: a.good + b.good + cross,
    pg,
    pc,
    sg,
    sc
  };
}

const tree = new Array(4 * N);

function build(node, left, right) {
  if (left === right) {
    tree[node] = leaf(values[left]);
    return;
  }
  const mid = (left + right) >> 1;
  build(node * 2, left, mid);
  build(node * 2 + 1, mid + 1, right);
  tree[node] = merge(tree[node * 2], tree[node * 2 + 1]);
}

function update(node, left, right, index, value) {
  if (left === right) {
    tree[node] = leaf(value);
    return;
  }
  const mid = (left + right) >> 1;
  if (index <= mid) update(node * 2, left, mid, index, value);
  else update(node * 2 + 1, mid + 1, right, index, value);
  tree[node] = merge(tree[node * 2], tree[node * 2 + 1]);
}

function query(node, left, right, ql, qr) {
  if (ql <= left && right <= qr) return tree[node];
  const mid = (left + right) >> 1;
  if (qr <= mid) return query(node * 2, left, mid, ql, qr);
  if (ql > mid) return query(node * 2 + 1, mid + 1, right, ql, qr);
  return merge(
    query(node * 2, left, mid, ql, qr),
    query(node * 2 + 1, mid + 1, right, ql, qr)
  );
}

build(1, 0, N - 1);

const output = [];
for (let i = 0; i < M; i++) {
  const type = input[pos++];
  const x = input[pos++];
  const y = input[pos++];
  if (type === 1) {
    update(1, 0, N - 1, x - 1, y);
  } else {
    output.push(String(query(1, 0, N - 1, x - 1, y - 1).good));
  }
}

process.stdout.write(output.join('\n'));
